/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    towerThornsFraction, THORN_DAMAGE_SCALE, THORN_LAB_INDEX, THORN_MODULE_BENEFIT_SLOT, thornDamageOnHit, thornAccumulatorNext
 * depends    src/mechanics/combat/types
 * used by    src/calculators/specs.generated, src/mechanics/combat/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { ThornDamageInput } from './types'

/** Displayed tower thorns as a fraction. Relic and Vault bonuses multiply the
 * workshop-plus-module amount; they do not add flat percentage points.
 * Player-observed formula: https://www.reddit.com/r/TheTowerGame/comments/1vfllkm/thorns_relic/
 * This stat conversion does not establish target-specific thorn resistance.
 */
export function towerThornsFraction(workshopFraction: number, moduleFraction: number,
  relicFraction = 0, vaultFraction = 0): number {
  if (![workshopFraction, moduleFraction, relicFraction, vaultFraction]
    .every(value => Number.isFinite(value) && value >= 0))
    throw new Error('THORNS_STAT_FINITE_NONNEGATIVE_REQUIRED')
  const result = (workshopFraction + moduleFraction) * (1 + relicFraction) * (1 + vaultFraction)
  if (!Number.isFinite(result)) throw new Error('THORNS_STAT_OVERFLOW')
  return result
}
/**
 * Thorn damage on enemy contact.
 *
 * Damage scales with enemy factor, thorn multiplier, optional lab tier, and module benefit.
 */

export const THORN_DAMAGE_SCALE = 0.01
export const THORN_LAB_INDEX = 28
export const THORN_MODULE_BENEFIT_SLOT = 2

export function thornDamageOnHit(input: ThornDamageInput): number {
  const scale = input.thornLabActive ? THORN_DAMAGE_SCALE : 1
  let dmg = input.enemyFactor * input.thornMultiplier * scale * input.contactDamage
  if (input.moduleBenefit != null) {
    dmg *= input.moduleBenefit
  }
  return dmg
}

export function thornAccumulatorNext(existing: number, thornMultiplier: number): number {
  return existing + thornMultiplier + 1
}
